 for(const x of [-1.6,1.8])this.box(x,0,-3.2,.13,1.1,3.1,'#d3cad6');for(const x of [-4.8,-.7,3.8])this.box(x,0,-.84,2.1,.65,.13,'#dbd1df');this.box(-.03,0,1.5,.13,.55,4.6,'#ddd2df');
